<?php
session_start();require_once '../config/database.php';require_once 'lib.php';if(!isset($_SESSION['user_id'])){header('Location: ../login.php');exit;}$railroad=ttOperationsRailroad($pdo,(int)$_SESSION['user_id']);$railroadId=(int)$railroad['id'];$id=(int)($_GET['id']??$_POST['id']??0);$error='';$message='';
function ttLoadWorkOrder(PDO $pdo,int $id,int $railroadId):array{$stmt=$pdo->prepare('SELECT sl.*,a.assignment_number,a.title_snapshot,a.operating_pattern,a.status assignment_status,a.operating_base_industry_id,a.starting_track,a.start_method,a.crew_name,a.end_plan,a.end_industry_id,a.end_track,a.predecessor_assignment_id,s.session_number,s.session_name,s.operating_date,i.industry_name base_name FROM operation_switch_lists sl JOIN operation_assignments a ON a.id=sl.assignment_id JOIN operating_sessions s ON s.id=sl.session_id LEFT JOIN industries i ON i.id=a.operating_base_industry_id WHERE sl.id=? AND sl.railroad_id=?');$stmt->execute([$id,$railroadId]);$row=$stmt->fetch(PDO::FETCH_ASSOC);if(!$row){http_response_code(404);die('Work order not found.');}return $row;}$list=ttLoadWorkOrder($pdo,$id,$railroadId);
if($_SERVER['REQUEST_METHOD']==='POST'){try{ttOperationsRequireCsrf();$action=(string)($_POST['action']??'');
 if($action==='approve'){$pdo->beginTransaction();$pdo->prepare("UPDATE operation_switch_lists SET status='cancelled',cancelled_at=NOW(),notes=CONCAT(COALESCE(notes,''),' Superseded by revision ',?) WHERE assignment_id=? AND railroad_id=? AND status='approved' AND id<>?")->execute([(int)$list['revision_number'],(int)$list['assignment_id'],$railroadId,$id]);$stmt=$pdo->prepare("UPDATE operation_switch_lists SET status='approved',approved_at=NOW(),approved_by_user_id=? WHERE id=? AND railroad_id=? AND status='draft'");$stmt->execute([(int)$_SESSION['user_id'],$id,$railroadId]);$pdo->prepare("UPDATE operation_assignments SET status=IF(predecessor_assignment_id IS NULL,'ready','waiting'),approved_at=NOW() WHERE id=? AND railroad_id=?")->execute([(int)$list['assignment_id'],$railroadId]);if($list['start_method']==='prepared_cut')$pdo->prepare("UPDATE prepared_cuts SET status='assigned' WHERE id=(SELECT prepared_cut_id FROM operation_assignments WHERE id=?) AND status='ready'")->execute([(int)$list['assignment_id']]);$pdo->commit();$message='Revision approved and frozen.';}
 elseif($action==='cancel'){$pdo->beginTransaction();$note=substr(trim((string)($_POST['cancel_note']??'')),0,5000);$pdo->prepare("UPDATE operation_switch_lists SET status='cancelled',cancelled_at=NOW(),notes=? WHERE id=? AND railroad_id=? AND status IN('draft','approved','in_progress','needs_review')")->execute([$note,$id,$railroadId]);$pdo->prepare("UPDATE operation_assignments SET status='cancelled',cancelled_at=NOW() WHERE id=? AND railroad_id=?")->execute([(int)$list['assignment_id'],$railroadId]);$pdo->prepare("UPDATE prepared_cuts SET status='ready' WHERE id=(SELECT prepared_cut_id FROM operation_assignments WHERE id=?) AND status='assigned'")->execute([(int)$list['assignment_id']]);$pdo->commit();$message='Work order cancelled. No equipment locations changed.';}
 elseif($action==='complete'){ttCompleteWorkOrder($pdo,$list,$railroadId,$_POST);$message='Work order completed and confirmed physical results applied.';}
 else throw new RuntimeException('Invalid work-order action.');$list=ttLoadWorkOrder($pdo,$id,$railroadId);
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}
$movesStmt=$pdo->prepare('SELECT m.*,oi.industry_name actual_industry_name FROM operation_switch_list_moves m LEFT JOIN industries oi ON oi.id=m.actual_industry_id WHERE m.switch_list_id=? AND m.railroad_id=? ORDER BY m.sequence_number');$movesStmt->execute([$id,$railroadId]);$moves=$movesStmt->fetchAll(PDO::FETCH_ASSOC);$industriesStmt=$pdo->prepare('SELECT id,industry_name FROM industries WHERE railroad_id=? AND active=1 ORDER BY industry_name');$industriesStmt->execute([$railroadId]);$industries=$industriesStmt->fetchAll(PDO::FETCH_ASSOC);$revisions=$pdo->prepare('SELECT id,revision_number,status FROM operation_switch_lists WHERE assignment_id=? AND railroad_id=? ORDER BY revision_number DESC');$revisions->execute([(int)$list['assignment_id'],$railroadId]);$revisions=$revisions->fetchAll(PDO::FETCH_ASSOC);
function ttCompleteWorkOrder(PDO $pdo,array $list,int $railroadId,array $post):void{$reasons=['track_blocked','car_inaccessible','no_capacity','bad_order','wrong_car','customer_not_ready','locomotive_issue','crew_issue','order_changed','other'];$pdo->beginTransaction();$lock=$pdo->prepare("SELECT status FROM operation_switch_lists WHERE id=? AND railroad_id=? FOR UPDATE");$lock->execute([(int)$list['id'],$railroadId]);if(!in_array($lock->fetchColumn(),['approved','in_progress','needs_review'],true))throw new RuntimeException('This work order cannot be completed.');$stmt=$pdo->prepare('SELECT * FROM operation_switch_list_moves WHERE switch_list_id=? AND railroad_id=? AND equipment_id IS NOT NULL ORDER BY sequence_number FOR UPDATE');$stmt->execute([(int)$list['id'],$railroadId]);$moves=$stmt->fetchAll(PDO::FETCH_ASSOC);$moved=0;$notMoved=0;$updateMove=$pdo->prepare('UPDATE operation_switch_list_moves SET actual_outcome=?,actual_industry_id=?,actual_track=?,actual_load_status=?,exception_reason_code=?,exception_notes=?,progress_complete=1,progress_updated_at=NOW(),completed_at=NOW() WHERE id=?');$lockEquipment=$pdo->prepare('SELECT current_industry_id,current_track,load_status FROM equipment WHERE id=? AND railroad_id=? FOR UPDATE');$updateEquipment=$pdo->prepare('UPDATE equipment SET current_industry_id=?,current_track=?,load_status=? WHERE id=? AND railroad_id=?');foreach($moves as $move){$key=(string)$move['id'];$outcome=(string)($post['outcome'][$key]??'');if(!in_array($outcome,['moved','not_moved'],true))throw new RuntimeException('Every car requires a Moved or Not Moved result.');$lockEquipment->execute([(int)$move['equipment_id'],$railroadId]);$equipment=$lockEquipment->fetch(PDO::FETCH_ASSOC);if(!$equipment)throw new RuntimeException('A planned car no longer belongs to this railroad.');$reason=null;$notes=substr(trim((string)($post['exception_notes'][$key]??'')),0,255);$actualIndustry=(int)($post['actual_industry_id'][$key]??$move['destination_industry_id']);$actualTrack=substr(trim((string)($post['actual_track'][$key]??$move['destination_track'])),0,120);$actualLoad=substr(trim((string)($post['actual_load_status'][$key]??$move['planned_load_status'])),0,64);if($outcome==='not_moved'){$reason=(string)($post['reason'][$key]??'');if(!in_array($reason,$reasons,true))throw new RuntimeException('Every Not Moved car needs a valid reason.');if($reason==='other'&&$notes==='')throw new RuntimeException('Other exceptions require notes.');$actualIndustry=(int)$equipment['current_industry_id'];$actualTrack=(string)$equipment['current_track'];$actualLoad=(string)$equipment['load_status'];$notMoved++;}else{if((int)$equipment['current_industry_id']!==(int)$move['origin_industry_id']||trim((string)$equipment['current_track'])!==trim((string)$move['origin_track']))throw new RuntimeException('Stale physical state detected for '.$move['reporting_marks_snapshot'].' '.$move['road_number_snapshot'].'. Its location changed after approval; no results were applied.');$valid=$pdo->prepare('SELECT id FROM industries WHERE id=? AND railroad_id=?');$valid->execute([$actualIndustry,$railroadId]);if(!$valid->fetchColumn())throw new RuntimeException('Choose a valid actual destination.');$updateEquipment->execute([$actualIndustry,$actualTrack,$actualLoad,(int)$move['equipment_id'],$railroadId]);$moved++;}$updateMove->execute([$outcome,$actualIndustry,$actualTrack,$actualLoad,$reason,$notes?:null,(int)$move['id']]);}
 $endIndustry=(int)$list['end_industry_id'];if($endIndustry<=0&&$list['end_plan']==='return_origin')$endIndustry=(int)$list['operating_base_industry_id'];if($endIndustry>0){$pdo->prepare('UPDATE equipment e JOIN operation_assignment_locomotives al ON al.equipment_id=e.id SET e.current_industry_id=?,e.current_track=? WHERE al.assignment_id=? AND e.railroad_id=?')->execute([$endIndustry,(string)($list['end_track']?:$list['starting_track']),(int)$list['assignment_id'],$railroadId]);}
 $pdo->prepare("UPDATE operation_switch_lists SET status='completed',completed_at=NOW(),moved_count=?,not_moved_count=? WHERE id=?")->execute([$moved,$notMoved,(int)$list['id']]);$pdo->prepare("UPDATE operation_assignments SET status='completed',completed_at=NOW() WHERE id=?")->execute([(int)$list['assignment_id']]);$pdo->prepare("UPDATE prepared_cuts SET status='released' WHERE id=(SELECT prepared_cut_id FROM operation_assignments WHERE id=?) AND status IN('assigned','in_use')")->execute([(int)$list['assignment_id']]);$dependents=$pdo->prepare("SELECT id,operating_base_industry_id FROM operation_assignments WHERE predecessor_assignment_id=? AND railroad_id=? AND status='waiting' FOR UPDATE");$dependents->execute([(int)$list['assignment_id'],$railroadId]);foreach($dependents->fetchAll(PDO::FETCH_ASSOC) as $dependent){$available=$notMoved===0;$pdo->prepare("UPDATE operation_assignments SET status=? WHERE id=?")->execute([$available?'ready':'needs_review',(int)$dependent['id']]);}$remaining=$pdo->prepare("SELECT COUNT(*) FROM operation_assignments WHERE session_id=? AND status NOT IN('completed','cancelled')");$remaining->execute([(int)$list['session_id']]);if((int)$remaining->fetchColumn()===0)$pdo->prepare("UPDATE operating_sessions SET status='completed',completed_at=NOW() WHERE id=? AND railroad_id=?")->execute([(int)$list['session_id'],$railroadId]);$pdo->commit();}
?>
<?php include '../includes/header.php';?><title><?=ttHtml($list['switch_list_number'])?> Work Order</title><link rel="stylesheet" href="../assets/css/operations.css"></head><body><?php include '../includes/navbar.php';?><div class="tt-operations-shell"><?php include '../assets/components/sidebar.php';?><section class="tt-ops-page"><div class="d-flex flex-wrap justify-content-between gap-3"><div><p class="tt-eyebrow">Switch List / Work Order</p><h1><?=ttHtml($list['switch_list_number'])?> — Revision <?=(int)$list['revision_number']?></h1><p class="lead mb-1"><?=ttHtml($list['title_snapshot'])?></p><p><?=ttHtml($list['operating_date'].' · '.$list['base_name'].' · Crew: '.($list['crew_name']?:'Unassigned'))?></p></div><span class="badge tt-status-<?=ttHtml($list['status'])?>"><?=ttHtml(ucwords(str_replace('_',' ',$list['status'])))?></span></div><?php if($message):?><div class="alert alert-success"><?=ttHtml($message)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=ttHtml($error)?></div><?php endif;?><?php if($list['diagnostic_summary']):?><div class="alert alert-info"><?=nl2br(ttHtml($list['diagnostic_summary']))?></div><?php endif;?><p>Revisions: <?php foreach($revisions as $rev):?><a class="badge text-bg-light" href="work_order.php?id=<?=(int)$rev['id']?>">Rev <?=(int)$rev['revision_number']?> · <?=ttHtml($rev['status'])?></a> <?php endforeach;?></p>
<form method="post" id="closeoutForm"><input type="hidden" name="csrf_token" value="<?=ttHtml(ttOperationsCsrfToken())?>"><input type="hidden" name="id" value="<?=$id?>"><div class="card mb-3"><div class="table-responsive"><table class="table tt-work-order-table mb-0"><thead><tr><th>Done</th><th>Photo</th><th>Car</th><th>Action</th><th>Instruction</th><th>From</th><th>Planned To</th><?php if(in_array($list['status'],['approved','in_progress','needs_review'],true)):?><th>Result</th><th>Actual destination</th><th>Exception</th><?php endif;?></tr></thead><tbody><?php foreach($moves as $move):?><tr><td><?php if($move['equipment_id']):?><input class="form-check-input tt-progress-check" type="checkbox" data-move-id="<?=(int)$move['id']?>" <?=$move['progress_complete']?'checked':''?> <?=in_array($list['status'],['approved','in_progress'],true)?'':'disabled'?>><?php endif;?></td><td><?php if($url=ttPhotoUrl($move['photo_filename_snapshot'])):?><button type="button" class="border-0 bg-transparent p-0 tt-photo-button" data-src="<?=ttHtml($url)?>" data-alt="<?=ttHtml(trim($move['reporting_marks_snapshot'].' '.$move['road_number_snapshot']))?>"><img class="tt-car-thumb" src="<?=ttHtml($url)?>" alt="<?=ttHtml(trim($move['reporting_marks_snapshot'].' '.$move['road_number_snapshot']))?>"></button><?php elseif($move['equipment_id']):?><span class="tt-no-photo">No Photo</span><?php endif;?></td><td><strong><?=ttHtml(trim($move['reporting_marks_snapshot'].' '.$move['road_number_snapshot']))?></strong><br><small><?=ttHtml($move['equipment_type_snapshot'].' · '.$move['service_snapshot'])?></small></td><td><strong><?=ttHtml($move['action'])?></strong></td><td><?=ttHtml($move['instruction'])?></td><td><?=ttHtml(trim($move['origin_name_snapshot'].' / '.$move['origin_track'],' /'))?></td><td><?=ttHtml(trim($move['destination_name_snapshot'].' / '.$move['destination_track'],' /'))?></td><?php if(in_array($list['status'],['approved','in_progress','needs_review'],true)):?><?php if($move['equipment_id']):?><td><select class="form-select form-select-sm" name="outcome[<?=(int)$move['id']?>]" required><option value="">Choose</option><option value="moved" <?=$move['actual_outcome']==='moved'?'selected':''?>>Moved</option><option value="not_moved" <?=$move['actual_outcome']==='not_moved'?'selected':''?>>Not Moved</option></select></td><td><select class="form-select form-select-sm" name="actual_industry_id[<?=(int)$move['id']?>]"><?php foreach($industries as $industry):?><option value="<?=(int)$industry['id']?>" <?=(int)($move['actual_industry_id']?:$move['destination_industry_id'])===(int)$industry['id']?'selected':''?>><?=ttHtml($industry['industry_name'])?></option><?php endforeach;?></select><input class="form-control form-control-sm mt-1" name="actual_track[<?=(int)$move['id']?>]" value="<?=ttHtml($move['actual_track']??$move['destination_track'])?>" placeholder="Actual track"><input type="hidden" name="actual_load_status[<?=(int)$move['id']?>]" value="<?=ttHtml($move['actual_load_status']??$move['planned_load_status'])?>"></td><td><select class="form-select form-select-sm" name="reason[<?=(int)$move['id']?>]"><option value="">None</option><?php foreach(['track_blocked'=>'Track blocked','car_inaccessible'=>'Car inaccessible','no_capacity'=>'No capacity / track full','bad_order'=>'Bad order','wrong_car'=>'Wrong car','customer_not_ready'=>'Customer not ready','locomotive_issue'=>'Locomotive issue','crew_issue'=>'Crew issue','order_changed'=>'Order changed','other'=>'Other'] as $v=>$label):?><option value="<?=$v?>" <?=$move['exception_reason_code']===$v?'selected':''?>><?=$label?></option><?php endforeach;?></select><input class="form-control form-control-sm mt-1" name="exception_notes[<?=(int)$move['id']?>]" value="<?=ttHtml($move['exception_notes'])?>" placeholder="Notes"></td><?php else:?><td colspan="3"></td><?php endif;?><?php endif;?></tr><?php endforeach;?></tbody></table></div></div><?php if(in_array($list['status'],['approved','in_progress','needs_review'],true)):?><div class="tt-closeout-controls"><button class="btn btn-success" name="action" value="complete" onclick="return confirm('Apply confirmed physical results and complete this work order?')">Complete / Apply Results</button></div><?php endif;?></form>
<div class="d-flex flex-wrap gap-2 mt-3"><a class="btn btn-outline-primary" href="print_order.php?id=<?=$id?>" target="_blank">Print / Reprint</a><?php if($list['status']==='draft'):?><form method="post"><input type="hidden" name="csrf_token" value="<?=ttHtml(ttOperationsCsrfToken())?>"><input type="hidden" name="id" value="<?=$id?>"><button class="btn btn-success" name="action" value="approve">Approve Revision</button></form><?php endif;?><?php if(!in_array($list['status'],['completed','cancelled'],true)):?><form method="post" onsubmit="return confirm('Cancel this work order? No equipment will move.')"><input type="hidden" name="csrf_token" value="<?=ttHtml(ttOperationsCsrfToken())?>"><input type="hidden" name="id" value="<?=$id?>"><input class="form-control d-inline-block w-auto" name="cancel_note" placeholder="Cancellation note"><button class="btn btn-outline-danger" name="action" value="cancel">Cancel</button></form><?php endif;?><a class="btn btn-secondary" href="switch_lists.php">All Work Orders</a></div></section></div><div class="tt-lightbox" id="photoLightbox" role="dialog" aria-modal="true" aria-label="Car photo"><button type="button" aria-label="Close">×</button><img alt=""></div><script>const token=<?=json_encode(ttOperationsCsrfToken())?>;document.querySelectorAll('.tt-progress-check').forEach(c=>c.addEventListener('change',async()=>{const body=new URLSearchParams({csrf_token:token,move_id:c.dataset.moveId,complete:c.checked?'1':'0'});const r=await fetch('progress.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body});if(!r.ok){c.checked=!c.checked;alert((await r.json()).error||'Unable to save progress');}}));const box=document.getElementById('photoLightbox'),img=box.querySelector('img'),close=()=>{box.classList.remove('is-open');};document.querySelectorAll('.tt-photo-button').forEach(b=>b.addEventListener('click',()=>{img.src=b.dataset.src;img.alt=b.dataset.alt;box.classList.add('is-open');box.querySelector('button').focus();}));box.querySelector('button').addEventListener('click',close);box.addEventListener('click',e=>{if(e.target===box)close();});document.addEventListener('keydown',e=>{if(e.key==='Escape')close();});</script><?php include '../includes/footer.php';?>
